CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', role INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_user_id ON sessions (user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_expires_at ON sessions (expires_at);
CREATE TABLE IF NOT EXISTS api_keys (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, name TEXT NOT NULL, key_hash TEXT NOT NULL UNIQUE, key_prefix TEXT NOT NULL, last_used TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_api_keys_user_id ON api_keys (user_id);
CREATE TABLE IF NOT EXISTS groups (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', created_by INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_groups_created_by ON groups (created_by);
CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY, name TEXT NOT NULL, platform TEXT NOT NULL, arch TEXT NOT NULL DEFAULT '', os_version TEXT NOT NULL DEFAULT '', hostname TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'offline', owner_id INTEGER NOT NULL, group_id TEXT, ip_address TEXT NOT NULL DEFAULT '', agent_id TEXT, agent_version TEXT NOT NULL DEFAULT '', metrics_json TEXT, last_seen TEXT NOT NULL DEFAULT '', expires_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_devices_owner_id ON devices (owner_id);
CREATE INDEX IF NOT EXISTS idx_devices_group_id ON devices (group_id);
CREATE INDEX IF NOT EXISTS idx_devices_agent_id ON devices (agent_id);
CREATE INDEX IF NOT EXISTS idx_devices_status ON devices (status);
CREATE TABLE IF NOT EXISTS agents (id TEXT PRIMARY KEY, device_id TEXT NOT NULL UNIQUE, owner_id INTEGER NOT NULL, version TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active', last_heartbeat TEXT NOT NULL, heartbeat_metrics TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_agents_owner_id ON agents (owner_id);
CREATE TABLE IF NOT EXISTS commands (id TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL, schedule TEXT NOT NULL DEFAULT '', content TEXT NOT NULL, target_type TEXT NOT NULL, target_ids_json TEXT NOT NULL, timeout INTEGER NOT NULL DEFAULT 1800, shell TEXT NOT NULL DEFAULT '', retry_policy_json TEXT, env_vars_json TEXT, status TEXT NOT NULL DEFAULT 'pending', next_run_at TEXT, created_by INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_commands_created_by ON commands (created_by);
CREATE INDEX IF NOT EXISTS idx_commands_status_next_run ON commands (status, next_run_at);
CREATE INDEX IF NOT EXISTS idx_commands_type ON commands (type);
CREATE TABLE IF NOT EXISTS command_targets (command_id TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, PRIMARY KEY (command_id, target_type, target_id));
CREATE INDEX IF NOT EXISTS idx_command_targets_lookup ON command_targets (target_type, target_id);
CREATE TABLE IF NOT EXISTS executions (id TEXT PRIMARY KEY, command_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', scheduled_for TEXT, started_at TEXT NOT NULL, completed_at TEXT, created_at TEXT NOT NULL, UNIQUE (command_id, scheduled_for));
CREATE INDEX IF NOT EXISTS idx_executions_command_id ON executions (command_id);
CREATE INDEX IF NOT EXISTS idx_executions_status ON executions (status);
CREATE TABLE IF NOT EXISTS execution_results (id TEXT PRIMARY KEY, execution_id TEXT NOT NULL, command_id TEXT NOT NULL, device_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', exit_code INTEGER NOT NULL DEFAULT 0, output TEXT NOT NULL DEFAULT '', log_content TEXT, timeout_at TEXT, started_at TEXT, completed_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (execution_id, device_id));
CREATE INDEX IF NOT EXISTS idx_execution_results_device_status ON execution_results (device_id, status);
CREATE INDEX IF NOT EXISTS idx_execution_results_status_timeout ON execution_results (status, timeout_at);
CREATE INDEX IF NOT EXISTS idx_execution_results_execution_id ON execution_results (execution_id);
CREATE INDEX IF NOT EXISTS idx_execution_results_command_id ON execution_results (command_id);
CREATE TABLE IF NOT EXISTS device_logs (id TEXT PRIMARY KEY, device_id TEXT NOT NULL, type TEXT NOT NULL, timestamp TEXT NOT NULL, message TEXT NOT NULL, metadata_json TEXT);
CREATE INDEX IF NOT EXISTS idx_device_logs_device_ts ON device_logs (device_id, timestamp);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, username TEXT NOT NULL DEFAULT '', action TEXT NOT NULL, target_id TEXT NOT NULL DEFAULT '', ip TEXT NOT NULL DEFAULT '', detail TEXT, timestamp TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_audit_logs_user_ts ON audit_logs (user_id, timestamp);
CREATE INDEX IF NOT EXISTS idx_audit_logs_ts ON audit_logs (timestamp);
